custom_css:
/* 作者：景然/春娴
*美化名称：梧桐树下
*禁止二传二改商用，如果你是买到的那就说明你被骗了。
*感谢墨千尾（discord@这对吗/inkfoxxxx）老师整理/编写的拼好码，使用到的代码已在贴内和css里注明。
*感谢教程贴
https://discord.com/channels/1291925535324110879/1380392618336194702
*感谢千尾老师的消息气泡右侧总空一块，感谢hy老师的隐藏思维链箭头，感谢Twelve老师的隐藏思维链背景只显示文字，隐藏qr，感谢Nn老师的自定义思维链文案，感谢易碎蝶老师的移出预设按钮，菜单按钮阴影，感谢Nini老师的隐藏qr，感谢dengdeng老师的隐藏弹窗，感谢Novely老师的菜单样式：图标，图标按钮，下拉箭头，输入数字框，输入文字框，选择框，勾选框，滑动条，标题，感谢莓乃滋老师的常用类名，感谢不在老师的选中user的区分和角色卡收藏与其他角色的区别，感谢camellia老师的简化了图标类名写法，感谢Nakari老师的头像布局代码，黄色类名解决，感谢珍珠老师的输入框隐藏代码，感谢Blue老师的解决提示词头部看不见的问题，感谢Deleted user老师的加载动画。*/

/* 导入自定义字体 */
@import url("https://fontsapi.zeoseven.com/437/main/result.css");

/* ===== 一、全局控制 ===== */
:root {
  --梧桐绿: #5f8b4c;
  --梧桐深绿: #3c5a2a;
  --梧桐浅绿: #a8c99e;
  --淡绿: #e2f0da;
  --纸色: #fef7e6;
  --白色气泡: #ffffff;
  --深绿控件: #6e8b4c;
  --浅绿控件: #c0ddb0;
  --main-text-color: #2D5A27;
  --italic-color: #6CC070;
  --underline-color: #49954D;
  --quote-color: #005904;
  --SmartThemeBodyColor: var(--main-text-color);
  --SmartThemeEmColor: var(--italic-color);
  --SmartThemeUnderlineColor: var(--underline-color);
  --SmartThemeQuoteColor: var(--quote-color);
  --SmartThemeShadowColor: rgba(0, 0, 0, 0);
  --SmartThemeChatTintColor: var(--纸色);
  --SmartThemeBlurTintColor: rgba(95, 139, 76, 0.2);
  --SmartThemeBorderColor: var(--梧桐浅绿);
  --SmartThemeUserMesBlurTintColor: var(--白色气泡);
  --SmartThemeBotMesBlurTintColor: var(--白色气泡);
  --fontScale: 1;
  --sheldWidth: 100%;
  --blurStrength: 8px;
  --shadowWidth: 0px;
  --bg-thumb-columns: 3;
  --自定义思维链文案: "🌿 梧桐絮语";
  --自定义“加载更多信息”文案: "📜 拂开落叶，查看更多";
  --自定义输入框文字: "🍂 在梧桐树下写点什么...";
}

body {
  font-family: "Huiwen-MinchoGBK", 'Segoe UI', 'Noto Sans', system-ui, sans-serif;
  background-color: var(--纸色);
  color: var(--main-text-color) !important;
}

em {
  color: var(--italic-color) !important;
  border-left: 2px solid var(--梧桐浅绿);
  padding-left: 6px;
}

u, ins {
  text-decoration-color: var(--underline-color) !important;
}

q, blockquote {
  color: var(--quote-color) !important;
}

/* ===== 代码块和行内代码美化 ===== */
pre {
  background-color: #e8f5e9 !important;
  color: #1b5e20 !important;
  padding: 12px !important;
  border-radius: 4px !important;
  overflow-x: auto !important;
  font-family: 'Courier New', monospace !important;
  font-size: 0.9em !important;
  border-left: 3px solid var(--梧桐绿) !important;
}

:not(pre) > code {
  background-color: #2e7d32 !important;
  color: #ffffff !important;
  padding: 2px 6px !important;
  border-radius: 4px !important;
  font-family: 'Courier New', monospace !important;
  font-size: 0.9em !important;
}

/* 全局弹出面板 - 白绿色渐变 */
.drawer-content,
#table_drawer_content,
.options-content {
  background: linear-gradient(145deg, #ffffff, var(--梧桐浅绿)) !important;
  border-color: var(--梧桐浅绿) !important;
  backdrop-filter: blur(4px);
}

/* ===== 二、顶栏 ===== */
#top-settings-holder {
  background: var(--淡绿);
  box-shadow: none !important;
  border: 1px solid var(--梧桐浅绿);
  border-radius: 0px;
}

#top-bar {
  border-radius: 0px !important;
  background-color: transparent !important;
}

#top-settings-holder .drawer-icon::before {
  font-size: inherit;
  color: inherit;
  background: none;
  -webkit-background-clip: unset;
  background-clip: unset;
  filter: none !important;
}

#top-settings-holder .drawer-icon:hover::before {
  transform: none;
  filter: none;
}

.drawer-icon {
  filter: none !important;
  box-shadow: none !important;
}

/* ===== 三、底栏 ===== */
#send_form {
  background: var(--淡绿);
  border-radius: 0px !important;
  border: 1px solid var(--梧桐浅绿) !important;
  padding: 8px;
  box-shadow: none !important;
}

#send_textarea {
  border-radius: 0px !important;
  background-color: var(--白色气泡) !important;
  border: 1px solid var(--梧桐浅绿) !important;
  color: #3a2a1f;
  box-shadow: none !important;
}

#send_form [class*="fa-"]::before {
  font-size: inherit;
  color: inherit;
  background: none;
  -webkit-background-clip: unset;
  background-clip: unset;
  filter: none !important;
}

#send_form [class*="fa-"]:hover::before {
  transform: none;
  color: inherit;
}

#nonQRFormItems {
  position: relative;
}

#send_textarea::placeholder {
  color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--自定义输入框文字);
  color: var(--梧桐浅绿);
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-style: italic;
  font-size: 0.8em;
  pointer-events: none;
  white-space: nowrap;
  background: transparent;
  padding: 0;
  border-radius: 0;
  z-index: 2;
}

/* ===== QR 按钮隐藏样式（聚焦显示） ===== */
.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.5s ease,
    transform 0.5s ease;
}

#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 120px;
  transform: translateY(0);
  pointer-events: auto;
}

#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.3s ease;
}

#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 200px;
  pointer-events: auto;
}

/* ===== 四、聊天区域 ===== */
#chat {
  background-image: url('https://iili.io/qsT8Bs9.png');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  background-attachment: fixed;
}

.mes_block {
  background: var(--白色气泡) !important;
  border: 1px solid var(--梧桐浅绿);
  border-radius: 0px;
  padding: 0 0 16px 0;
  box-shadow: none !important;
  transition: none;
  position: relative;
}

.mes_block:hover {
}

.mes_text,
.timestamp,
.mes_block > div:not(.mesAvatarWrapper):not(.name_text):not(.tokenCounterDisplay):not(.mes_timer):not(.mesIDDisplay) {
  margin-left: 18px !important;
  margin-right: 18px !important;
}

.mes .mes_text {
  width: auto;
  padding: 0;
  margin-left: 18px !important;
  margin-right: 18px !important;
}

.mes_block::before {
  content: "";
  display: block;
  width: calc(100% + 36px);
  margin-left: -18px;
  margin-right: -18px;
  margin-top: 0;
  margin-bottom: 0;
  aspect-ratio: 4 / 3;
  background-image: url('https://iili.io/qsBLoSj.png');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  border: none;
  border-radius: 0px;
  box-sizing: border-box;
}

.mes_block:hover::before {
}

/* ===== 头像、名字、三元素 ===== */
.mesAvatarWrapper {
  position: absolute !important;
  top: 162px;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-12deg);
  z-index: 5;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  pointer-events: auto;
}

.mesAvatarWrapper .avatar img {
  width: 82px;
  height: 82px;
  border-radius: 0px;
  border: none !important;
  box-shadow: none !important;
  object-fit: cover;
}

.mesAvatarWrapper .avatar {
  pointer-events: auto;
}

.name_text {
  position: absolute !important;
  transform: translateX(-50%) rotate(-11deg);
  top: 210px;
  left: 58%;
  white-space: normal;
  max-width: 120px;
  text-align: center;
  background: transparent !important;
  padding: 0 !important;
  font-weight: bold;
  color: var(--梧桐深绿);
  font-size: 14px;
  z-index: 5;
  margin: 0 !important;
  line-height: 1.2;
  pointer-events: none;
}

.tokenCounterDisplay,
.mes_timer,
.mesIDDisplay {
  position: absolute !important;
  top: -60px;
  right: -100px;
  display: block !important;
  background: #ffffff !important;
  padding: 4px 10px;
  border-radius: 4px;
  box-shadow: none !important;
  font-size: 0.75rem;
  color: var(--梧桐深绿);
  white-space: nowrap;
  z-index: 6;
  margin-top: 0;
}

.mesIDDisplay {
  margin-top: 0;
}

.mes_timer {
  margin-top: 28px;
}

.tokenCounterDisplay {
  margin-top: 56px;
}

.mes {
  position: relative;
}

/* ===== 五、滚动条隐藏 ===== */
::-webkit-scrollbar {
  display: none !important;
}

* {
  scrollbar-width: none !important;
}

/* ===== 六、正则+脚本易读+防误触 ===== */
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
}

.regex-script-label.flex-container,
.flex-container .script-item {
  flex-wrap: wrap !important;
  padding: 6px 12px;
  border-radius: 0px;
  margin-bottom: 6px;
  background: rgba(95,139,76,0.08);
  border: 1px solid var(--梧桐浅绿);
}

.regex-script-label.flex-container .regex_script_name,
.script-item .script-item-name {
  flex-basis: 100%;
  white-space: normal;
  color: var(--梧桐深绿);
  font-weight: bold;
}

/* ===== 七、“加载更多消息” ===== */
#show_more_messages {
  font-size: 0 !important;
  color: transparent !important;
  display: block;
  padding: 10px 24px;
  margin: 20px auto;
  width: fit-content;
  background-color: var(--梧桐绿);
  border: 1px solid var(--梧桐浅绿);
  border-radius: 0px;
  cursor: pointer;
  transition: all 0.3s;
  box-shadow: none !important;
}

#show_more_messages::before {
  content: var(--自定义“加载更多信息”文案);
  font-size: 15px;
  color: var(--纸色);
  font-weight: 500;
}

#show_more_messages:hover {
  background-color: var(--梧桐深绿);
  transform: scale(1.02);
}

/* ===== 八、思维链美化（透明背景，与消息按钮同行） ===== */
.mes_reasoning_summary {
  list-style: none;
  cursor: pointer;
  display: flex !important;
  align-items: center;
  gap: 8px;
  margin: 5px 18px;
  position: relative;
  z-index: 4;
}

.mes_reasoning_summary::-webkit-details-marker {
  display: none;
}

details > summary {
  list-style: none;
}

details > summary::-webkit-details-marker {
  display: none;
}

.mes_reasoning_header {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 0 !important;
  margin-bottom: 0 !important;
  color: #C1B8B5 !important;
  font-size: 0.9em !important;
  display: inline-flex !important;
  align-items: center !important;
  transition: none !important;
  gap: 4px;
}

.mes_reasoning_summary:hover .mes_reasoning_header {
  transform: none;
  box-shadow: none;
}

.mes_reasoning_header_title {
  font-size: 0 !important;
}

.mes_reasoning_header_title::before {
  content: "🍃 梧桐絮语";
  font-size: 13px;
  color: var(--梧桐深绿);
  font-weight: bold;
}

.mes_reasoning_arrow {
  display: none !important;
}

.mes_buttons {
  position: absolute !important;
  right: 18px;
  top: 5px;
  display: flex;
  gap: 8px;
  z-index: 5;
}

.mes_buttons .mes_button {
  background: transparent;
  border: none;
  color: var(--梧桐浅绿);
  cursor: pointer;
  font-size: 14px;
  padding: 4px;
  filter: none !important;
}

.mes_buttons .mes_button:hover {
  color: var(--梧桐深绿);
  transform: scale(1.05);
}

.mes_reasoning {
  margin: 8px 18px 0 18px;
  padding: 12px;
  background-color: rgba(95,139,76,0.05);
  border-left: 3px solid var(--梧桐绿);
  border-radius: 0px;
  color: #4a3a28;
  font-family: monospace;
  font-size: 13px;
  max-height: 200px;
  overflow-y: auto;
}

/* ===== 九、全局控件样式 ===== */
.inline-drawer-header,
#world_info .inline-drawer-header,
#completion_prompt_manager .inline-drawer-header,
.standoutHeader,
#user-settings-block h4,
#user-settings-block .inline-drawer-header,
#extensions_settings .inline-drawer-header,
#extensions_settings2 .inline-drawer-header {
  background-color: var(--深绿控件) !important;
  border: none !important;
  color: #ffffff !important;
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
  padding: 8px 12px !important;
  font-weight: bold;
}

dialog.popup,
#select_chat_popup,
select,
.list-group,
.select2-dropdown,
#options,
#options-content,
#extensionsMenu {
  box-shadow: none !important;
}

.text_pole,
select,
input[type="text"],
input[type="number"],
input[type="search"],
#settingsSearch,
.popup textarea,
#description_textarea,
#firstmessage_textarea,
.edit_textarea.mdHotkeys,
.reasoning_edit_textarea,
.select2-container--default .select2-selection--single,
.select2-container--default .select2-selection--multiple {
  background-color: var(--浅绿控件) !important;
  color: #2c3e2f !important;
  border: none !important;
  padding: 4px 8px !important;
  border-radius: 0px !important;
  box-shadow: none !important;
}

.text_pole::placeholder,
select::placeholder,
input::placeholder,
textarea::placeholder {
  color: rgba(44, 62, 47, 0.7) !important;
}

input[type="checkbox"] {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  background-color: var(--浅绿控件);
  border: none;
  outline: none;
  box-shadow: none;
  cursor: pointer;
  position: relative;
}

input[type="checkbox"]:checked {
  background-color: var(--深绿控件);
}

input[type="checkbox"]:checked::before {
  content: "✓";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: #ffffff;
  font-size: 14px;
  font-weight: bold;
  width: auto;
  height: auto;
  background: none;
  box-shadow: none;
  display: block !important;
}

* {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
  filter: none !important;
  box-shadow: none !important;
}

/* ===== 十、收藏栏左右滑动 ===== */
.hotswap.avatars_inline {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-right: 15px;
}

.hotswap.avatars_inline::-webkit-scrollbar {
  display: block;
  height: 4px;
}

.hotswap.avatars_inline::-webkit-scrollbar-thumb {
  background: var(--梧桐绿);
}

@media (max-width: 768px) {
  .hotswap.avatars_inline {
    overflow: auto;
  }
}

.drawer-icon,
#send_form,
.mes_block,
.mes .avatar img,
input,
button,
.select,
.drawer-content {
  border-radius: 0px !important;
}

hr {
  border-top: 2px solid var(--梧桐浅绿);
}

a {
  color: var(--梧桐深绿);
}

a:hover {
  color: var(--梧桐绿);
}

/* ===== 十一、预设/正则/角色卡选择状态样式 ===== */
.completion_prompt_manager_prompt_disabled {
  background-color: var(--浅绿控件) !important;
  color: #000000 !important;
  opacity: 0.9;
}

.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
  background-color: var(--深绿控件) !important;
  color: #000000 !important;
}

.prompt-manager-inspect-action,
.prompt-manager-inspect-action * {
  color: inherit !important;
}

.regex-script-label:not(:has(input[type="checkbox"]:checked)) {
  background-color: var(--浅绿控件) !important;
  color: #000000 !important;
}

.regex-script-label:has(input[type="checkbox"]:checked) {
  background-color: var(--深绿控件) !important;
  color: #000000 !important;
}

.character_select.entity_block.flex-container.interactable.is_fav,
#user_avatar_block .bogus_folder_select,
#user_avatar_block .character_select,
#user_avatar_block .avatar-container.selected {
  background-color: var(--深绿控件) !important;
  border-color: var(--梧桐绿) !important;
}

#rm_characters_block .bogus_folder_select,
#rm_characters_block .character_select,
#rm_characters_block .avatar-container.selected {
  background-color: var(--浅绿控件) !important;
  border-color: var(--梧桐浅绿) !important;
}

.avatar-container {
  background-color: #f0f0f0 !important;
}

.avatar-container.selected {
  background-color: var(--深绿控件) !important;
  color: #000000 !important;
}

#user_avatar_block .avatar-container.selected {
  background-color: var(--深绿控件) !important;
}

.completion_prompt_manager_prompt_disabled *,
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) *,
.regex-script-label *,
.character_select.entity_block.flex-container.interactable.is_fav *,
#user_avatar_block .bogus_folder_select *,
#user_avatar_block .character_select *,
#user_avatar_block .avatar-container.selected *,
#rm_characters_block .bogus_folder_select *,
#rm_characters_block .character_select *,
#rm_characters_block .avatar-container.selected *,
.avatar-container.selected * {
  color: #000000 !important;
}

.completion_prompt_manager_header {
  color: var(--SmartThemeBodyColor) !important;
}
.character_select.is_fav .avatar {
  outline: 2px solid #3c5a2a;
  outline-offset: 2px;
}

.character_select.is_fav .ch_name {
  color: #3c5a2a;
}

#preloader {
  position: fixed;
  margin: 0;
  padding: 0;
  top: 0;
  left: 0;
  z-index: 999999;
  width: 100vw;
  height: 100vh;
  background-color: transparent;
  background-image: url('https://iili.io/qs8cjZN.png');
  background-size: 80% auto;
  background-position: center;
  background-repeat: no-repeat;
  opacity: 1;
}

#load-spinner {
  --spinner-size: 2em;
  background: linear-gradient(135deg, #ffffff, #c0ddb0);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  transition: all var(--animation-duration-2x) ease-out;
  opacity: 1;
  top: calc(50% - var(--spinner-size) / 2);
  left: calc(50% - var(--spinner-size) / 2);
  position: absolute;
  width: var(--spinner-size);
  height: var(--spinner-size);
  display: flex;
  align-items: center;
  justify-content: center;
}
